-- ----------------------------------------------------------------
-- Creatures take their health from base health x the sniffed modifier, as retail.
--
-- The server computes health as the base health of a creature's level, class and
-- expansion times HealthMultiplier (and mana as BaseMana x PowerMultiplier) when the
-- creature has an expansion, else it reads the stored health. The base health takes
-- Cata Classic's NPC health tables, which reproduce 65 of the 77 health values
-- sniffed on 15595 (the old table 61, the stored values 47), with levels 86-90 added;
-- 40560 creatures sniffed on 15595 take their expansion (the 4.3.4-era value) and the
-- sniffed health and mana modifiers. Summoned creatures, pets and creatures whose
-- class differs from the sniffed one keep their stored values.
-- ----------------------------------------------------------------
DROP PROCEDURE IF EXISTS `update_mangos`;

DELIMITER $$

CREATE PROCEDURE `update_mangos`()
BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        SHOW ERRORS;
        SELECT '* UPDATE FAILED *' AS `===== Status =====`,
               @cCurResult AS `===== DB is on Version: =====`;
        RESIGNAL;
    END;

    SET @cCurVersion := (SELECT `version` FROM `db_version` ORDER BY `version` DESC, `structure` DESC, `content` DESC LIMIT 0,1);
    SET @cCurStructure := (SELECT `structure` FROM `db_version` ORDER BY `version` DESC, `structure` DESC, `content` DESC LIMIT 0,1);
    SET @cCurContent := (SELECT `content` FROM `db_version` ORDER BY `version` DESC, `structure` DESC, `content` DESC LIMIT 0,1);

    SET @cOldVersion = '22';
    SET @cOldStructure = '15';
    SET @cOldContent = '005';

    SET @cNewVersion = '22';
    SET @cNewStructure = '15';
    SET @cNewContent = '006';
    SET @cNewDescription = 'Creature_Health_Model';
    SET @cNewComment = 'Creatures take their health from base health x the sniffed modifier, as retail';

    SET @cCurResult := (SELECT `description` FROM `db_version` ORDER BY `version` DESC, `structure` DESC, `content` DESC LIMIT 0,1);
    SET @cOldResult := (SELECT `description` FROM `db_version` WHERE `version` = @cOldVersion AND `structure` = @cOldStructure AND `content` = @cOldContent);
    SET @cNewResult := (SELECT `description` FROM `db_version` WHERE `version` = @cNewVersion AND `structure` = @cNewStructure AND `content` = @cNewContent);

    IF (@cCurResult = @cOldResult) THEN
